```python
def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    def dfs(node, path):
        if node == goal:
            return path
        for neighbor in graph[node]:
            if neighbor not in path:
                new_path = dfs(neighbor, path + [neighbor])
                if new_path:
                    return new_path
        return None

    return dfs(start, [start])

