def find_path(graph, start, goal):
    # Initialize a set of explored nodes
    explored = set()

    # Initialize a dictionary to maintain path information
    path = {start: [start]}

    # Initialize a queue for BFS-like search
    queue = [start]

    while queue:
        current = queue.pop(0)

        if current == goal:
            return path[current]

        explored.add(current)

        for neighbor in graph.get(current, []):
            if neighbor not in explored and neighbor not in path:
                queue.append(neighbor)
                path[neighbor] = path[current] + [neighbor]

    # If goal is not reachable
    return None
