def find_path(graph, start, goal):
    def dfs(current_node, path):
        # Add the current node to the path (including the start node if it's the first visit)
        if current_node not in path:
            path.append(current_node)
        # Base case: if we reach the goal, return the path
        if current_node == goal:
            return path
        # Recursive case: explore the neighbors of the current node
        for neighbor in graph.get(current_node, []):
            if neighbor not in path:
                result = dfs(neighbor, path.copy())  # Copy path to avoid modifying the original
                if result is not None:
                    return result
        # If no path is found from this node, backtrack and remove the current node from the path
        path.pop()
        return None

    return dfs(start, [start])

